import os

csv_files = []
for root, dirs, files in os.walk("."):
    for f in files:
        if f.lower().endswith((".csv", ".tsv", ".xlsx", ".xls", ".parquet")):
            csv_files.append(os.path.join(root, f))

print("Data files found:", csv_files if csv_files else "None")
print("\nFull listing:")
for root, dirs, files in os.walk("."):
    for f in files:
        print(os.path.join(root, f))
